// NHMRC application representation; source-pinned field contracts, not a generic prefix rule.
(ReadFile as function, ArchiveBase as text, ExpectedBatch as text, TrustedRuleSHA256 as text) as list =>
let
    Manifest=Json.Document(ReadFile(ArchiveBase&"/manifest.json")),
    Checked=if Manifest[kind]="nhmrc_app_crosswalk_retention_v1" and Manifest[batch]=ExpectedBatch and Manifest[namespace]="nhmrc" and Manifest[complete]=true then Manifest else error "Crossref award packet identity drift",
    ReadRaw=(Name as text) as binary => let F=List.Select(Checked[files],each [name]=Name),B=Binary.Buffer(ReadFile(ArchiveBase&"/"&Name)),Pinned=if Name="rule-authority.json" then F else List.Select(Rule[source_files],each [name]=Name),Valid=List.Count(F)=1 and List.Count(Pinned)=1 and F{0}[sha256]=Pinned{0}[sha256] and F{0}[bytes]=Pinned{0}[bytes] and Binary.Length(B)=F{0}[bytes] in if Valid then B else error "Crossref award file identity or length drift",
    Read=(Name as text) as record => Json.Document(ReadRaw(Name)),
    RuleEntries=List.Select(Checked[files],each [name]="rule-authority.json"),
    Rule=if List.Count(RuleEntries)=1 and RuleEntries{0}[sha256]=TrustedRuleSHA256 and Text.Length(TrustedRuleSHA256)=64 then Read("rule-authority.json") else error "External APP rule authority drift",
    AuthorityFiles={{"rgms-guide.pdf","92c37f512dca324ae2da039f3dea11a69d5f0901044c893d908ea11232477a3a"},{"data-dictionary.xlsx","a78740d1d3bd8686128969a7d51f5fee76528f18667648605e135b57467129d0"},{"ardc-nhmrc-terms.html","d856d8bb0858b336b2bd86aee504f2c853d82e6a0c7760e7133fe59660fd1bd8"}},
    Policy=if Rule[rule]="nhmrc-application-number-representation-v1" and Rule[guide_page]=21 and List.AllTrue(List.Transform(AuthorityFiles,(A)=>let F=List.Select(Checked[files],each [name]=A{0}) in List.Count(F)=1 and F{0}[sha256]=A{1} and Binary.Length(ReadRaw(A{0}))=F{0}[bytes])) then Rule else error "APP primary authority drift",
    ApplicationNumber=(N as text) as nullable text => let D=if Text.Length(N)>=3 then Text.Range(N,3) else "",Code=Text.StartsWith(N,"APP") and Text.Length(N)=10 and Text.Select(D,{"0".."9"})=D and not Text.StartsWith(D,"0") in if Code then D else null,
    AuthorityEntries=List.Select(Checked[files],each [name]="authority-ror.json"),
    Authority=if List.Count(AuthorityEntries)=1 then Read("authority-ror.json") else error "Crossref authority provenance hash drift",
    AuthorityROR=if List.AnyTrue(List.Transform(Authority[links],each [type]="website" and [value]="https://www.nhmrc.gov.au/")) then Authority[id] else error "Crossref award funder authority drift",
    FunderIDs=List.Buffer(List.Combine(List.Transform(List.Select(Authority[external_ids],each [type]="fundref"),each List.Transform([all],(V)=>"10.13039/"&V)))),
    DOI=(S as text) as text => let T=Text.Lower(Text.Trim(S)),Prefixes={"https://doi.org/","http://doi.org/","https://dx.doi.org/","http://dx.doi.org/"},P=List.First(List.Select(Prefixes,each Text.StartsWith(T,_)),null) in if P=null then T else Text.Range(T,Text.Length(P)),
    Lookups=List.Buffer(List.Transform(Policy[ardc],(Q)=>let D=Read(Q[filename]),F=List.Select(Checked[files],each [name]=Q[filename]),Valid=Q[complete]=true and D[status]="OK" and D[code]="200" and D[data][offset]=0 and D[data][numFound]=List.Count(D[data][records]) and List.Count(F)=1 and Q[sha256]=F{0}[sha256] in if Valid then [Query=Q,Records=List.Buffer(D[data][records])] else error "Incomplete Crossref grant lookup")),
    Count=(S as text,T as text) as number => List.Count(Text.Split(S,T))-1,
    Institutional=(N as text,P as text) as nullable record => let Qs=List.Select(Record.FieldOrDefault(Policy,"institutional",{}),each [original_identifier]=N and [doi]=P),Q=if List.Count(Qs)=1 then Qs{0} else null,Bare=ApplicationNumber(N),Pub=if Q=null then "" else Text.FromBinary(ReadRaw(Q[publication_filename]),TextEncoding.Utf8),Project=if Q=null then "" else Text.FromBinary(ReadRaw(Q[project_filename]),TextEncoding.Utf8),URI=if Bare=null then "" else "http://purl.org/au-research/grants/nhmrc/"&Bare,DOIMeta="name=""citation_doi"" content="""&P&"""",ProjectLink=if Q=null then "" else "rel=""UPMProject"" href="""&Q[project_url]&"""",GrantLink="href="""&URI&"""",TableStart="<table class=""properties funders_informations_table"">",Funding=try Text.BeforeDelimiter(Text.AfterDelimiter(Pub,TableStart),"</table>") otherwise "",FunderStart="<tr><td>NHMRC National Health and Medical Research Council </td><td>",Numbers=try Text.BeforeDelimiter(Text.AfterDelimiter(Funding,FunderStart),"</td>") otherwise "",Valid=Q<>null and Bare<>null and Count(Pub,DOIMeta)=1 and Count(Pub,ProjectLink)=1 and Count(Project,GrantLink)=1 and Count(Pub,TableStart)=1 and Count(Funding,FunderStart)=1 and List.Contains(List.Transform(Text.Split(Numbers,","),each Text.Trim(_)),Bare) in if Valid then [URI=URI,Query=Q] else null,
    Rows=List.Combine(List.Transform(Policy[crossref],(Q)=>let D=Read(Q[filename]),W=D[message],P=DOI(Q[doi]),F=List.Select(Checked[files],each [name]=Q[filename]),Valid=D[status]="ok" and DOI(W[DOI])=P and Text.StartsWith(P,"10.") and List.Count(F)=1 and Q[sha256]=F{0}[sha256],Funders=if Valid then Record.FieldOrDefault(W,"funder",{}) else error "Crossref publication identity drift" in List.Combine(List.Transform(Funders,(FR)=>let FID=DOI(Record.FieldOrDefault(FR,"DOI","")),Numbers=if List.Contains(FunderIDs,FID) then Record.FieldOrDefault(FR,"award",{}) else {} in List.RemoveNulls(List.Transform(Numbers,(N)=>let
        Ls=List.Select(Lookups,each [Query][original_identifier]=N),L=if List.Count(Ls)=1 then Ls{0} else null,Bare=ApplicationNumber(N),URI=if Bare=null then null else "https://purl.org/au-research/grants/nhmrc/"&Bare,
        Matches=if L=null or Bare=null then {} else List.Select(L[Records],each Record.FieldOrDefault(_,"type","")="grant" and Record.FieldOrDefault(_,"purl","")=URI and List.Contains(Record.FieldOrDefault(_,"identifiers",{}),Bare)),
        Inst=if List.IsEmpty(Matches) and Bare<>null then Institutional(N,P) else null,ResolvedURI=if Inst<>null then Inst[URI] else URI,
        ProvenanceBase=if L=null then "" else Text.FromBinary(Json.FromValue([relationship="issuer_defined_application_representation",funderDOI=FID,awardNumber=N,applicationNumber=Bare,rule=Policy[rule],ruleAuthoritySHA256=TrustedRuleSHA256,guideSHA256=AuthorityFiles{0}{1},guidePage=21,dictionarySHA256=AuthorityFiles{1}{1},registryTermsSHA256=AuthorityFiles{2}{1},ardcRawSHA256=L[Query][sha256],ardcSourceURL=L[Query][url],authorityROR=AuthorityROR,authorityRawSHA256=AuthorityEntries{0}[sha256]]),TextEncoding.Utf8),
        Provenance=if Inst=null then ProvenanceBase else Text.FromBinary(Json.FromValue(Record.Combine({Json.Document(ProvenanceBase),[relationship="explicit_institutional_application_identifier_chain",institutionalPublicationURL=Inst[Query][publication_url],institutionalPublicationSHA256=List.First(List.Select(Checked[files],each [name]=Inst[Query][publication_filename]))[sha256],institutionalProjectURL=Inst[Query][project_url],institutionalProjectSHA256=List.First(List.Select(Checked[files],each [name]=Inst[Query][project_filename]))[sha256],ardcExactIdentifierAbsent=true]})),TextEncoding.Utf8)
        in if List.Count(Matches)=1 or (L<>null and List.IsEmpty(Matches) and Inst<>null) then [EvidenceKey=Text.Combine({"crossref:"&P,"publication_award_crosswalk","doi:"&P,ResolvedURI},"|"),RelationshipKind="publication_award_crosswalk",SourceWorkID="crossref:"&P,PublicationDOI=P,PublicationPMID="",ReferenceType=Provenance,FromKey="doi:"&P,ToKey=ResolvedURI,FromLabel=FID,ToLabel=N,ORCID="",ORCIDStatus="Absent",ROR=AuthorityROR,IdentityStatus="Source-supported",SourceURL=Q[url],ObservedUTC=Q[observed_utc],RawSHA256=Q[sha256],SourceVersion=ExpectedBatch,ReviewState="Not reviewed",AuthenticationState="Not authenticated"] else null)))))),
    Output=if List.IsEmpty(Rows) then #table({"EvidenceKey"},{}) else Table.FromRecords(Rows),
    Groups=Table.Group(Output,{"EvidenceKey"},{{"Rows",each Table.Distinct(_),type table}}),
    Result=if List.AllTrue(List.Transform(Groups[Rows],each Table.RowCount(_)=1)) then Table.ToRecords(Table.Distinct(Output,{"EvidenceKey"})) else error "Conflicting repeated Crossref grant assertion"
in List.Buffer(Result)
